INSERT INTO submissions (id, round_id, song_id, submitter_id, comment, created_at, vote_total) VALUES
  (1, 1, 1, 2, 'Lost in your mind when you’re trying to make a big decision, and sometimes you need someone else to help pull you out of that place', '2025-05-01T14:13:39Z', 3),
