  (6, 1, 6, 3, 'If you make it through the bit of screaming at the beginning, chorus is a bop', '2025-04-30T19:37:54Z', 2),
  (7, 1, 7, 1, 'a throwback… 63 million streams for a reason ', '2025-04-30T20:53:10Z', 9),
