  (9, 1, 9, 6, NULL, '2025-05-01T15:42:44Z', 4),
  (10, 2, 10, 9, 'why not dance through the end times?', '2025-05-03T19:08:36Z', 4),
  (11, 2, 11, 7, NULL, '2025-05-03T22:33:53Z', 7),
  (12, 2, 12, 8, '“ And I looked, and behold a pale horse: and his name that sat on him was Death, and Hell followed with him.”', '2025-05-03T12:01:09Z', 6),
  (13, 2, 13, 5, NULL, '2025-05-03T12:32:08Z', 3),
  (14, 2, 14, 2, 'It’s literally the apocalypse', '2025-05-03T22:01:58Z', 3),
  (15, 2, 15, 6, NULL, '2025-05-03T15:05:46Z', 8),
  (16, 2, 16, 1, NULL, '2025-05-03T19:08:30Z', 4),
  (17, 2, 17, 4, 'Written under the ever-present threat of nuclear annihilation around the Cuban missile crisis ', '2025-05-03T15:12:50Z', 7),
  (18, 2, 18, 3, 'In the running for heaviest song of all time I think. The end feels like you’re being progressively slammed further and further into the center of the earth', '2025-05-03T12:11:57Z', 3),
