  (70, 8, 70, 6, NULL, '2025-05-13T04:19:03Z', 3),
  (71, 8, 71, 8, 'The climax of any great bar karaoke night. In Miller Lite fueled joy, the whole place is belting out the last refrain together. No other song comes close for me in fun and finality.', '2025-05-12T21:46:34Z', 8),
  (72, 8, 72, 2, NULL, '2025-05-12T21:40:32Z', 4),
  (73, 9, 73, 6, NULL, '2025-05-18T20:49:59Z', 5),
  (74, 9, 74, 2, 'Deeply nostalgic song on one of the greatest albums of all time', '2025-05-19T16:03:20Z', -2),
  (75, 9, 75, 8, 'Anxiety. Fear. Dread. Hope. Courage. Peace. An incredibly cathartic song that spans the whole emotional spectrum and can always be returned to.', '2025-05-18T21:02:37Z', 3),
