INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (701, 130, 4, 0, 'Sorry ladies, this is a boys round

^this was the comment I had here for 10 min before I realized this singer is actually a man. Went back and listened to the song again and realized there is no way I could have thought that, and therefore the song must have left so little of an impression that I forgot the gender of the singer. Also, terminal case of zoomer voice.', '2025-05-26T13:43:52Z'),
  (702, 131, 4, 1, 'Yep yep yep Darius knows what’s up. I always wonder what the Blowfish are up to these days ', '2025-05-26T13:43:52Z'),
  (703, 132, 4, -1, '“You are sheltering an attempt at a hit pop song in your sad boy summer, are you not?”', '2025-05-26T13:43:52Z'),
  (704, 124, 8, 0, 'The Catholic communists at Hillsdale told me to like Radiohead but idk it never worked ', '2025-05-26T18:36:32Z'),
  (705, 125, 8, 0, 'Forgettable', '2025-05-26T18:36:32Z'),
  (706, 126, 8, 0, 'Nice', '2025-05-26T18:36:32Z'),
  (707, 127, 8, 0, 'Truly terrible, I’m assuming a Corey or Joseph poast?', '2025-05-26T18:36:32Z'),
  (708, 128, 8, -1, 'Sufjan rose from rags to riches by embodying the emotivism and sensitivity that women narcissistically wish men had. However a fruit with a banjo does not sad boy summer make.', '2025-05-26T18:36:32Z'),
  (709, 130, 8, 0, 'AI Generated', '2025-05-26T18:36:32Z'),
  (710, 131, 8, 3, 'Best song in this garbage dump of a round and it’s not even close. Darius alone is top tier Sammybait, but in composition and tone this song works too well.', '2025-05-26T18:36:32Z'),
  (711, 129, 8, 0, 'Great song.', '2025-05-26T18:36:32Z'),
  (712, 132, 8, 0, 'Somehow worse than the other AI song maybe it’s a Lewis thing?', '2025-05-26T18:36:32Z'),
  (713, 135, 2, 2, 'Wow this is perfect', '2025-05-27T15:47:07Z'),
  (714, 137, 2, 1, 'This was fantastic ', '2025-05-27T15:47:07Z'),
  (715, 138, 2, 0, 'Love seeing Phoebe Bridgers and Julien Baker here but I didn’t get it until the chorus ', '2025-05-27T15:47:07Z'),
  (716, 139, 2, -1, 'Great song but this was the least resonant of the lot for me', '2025-05-27T15:47:07Z'),
  (717, 140, 2, 0, 'I liked this a lot, surprised me', '2025-05-27T15:47:07Z'),
  (718, 142, 2, 0, 'I’ve never thought of this song as Christological before but now every time I hear it I will think of St. Faustina. Thank you for this ', '2025-05-27T15:47:07Z'),
  (719, 135, 4, 0, 'Love this and it’s a fantastic love song, but errs too far on that side to get the vote from me. ', '2025-05-27T17:36:09Z'),
  (720, 133, 4, 1, 'I came in expecting to pass this one over - but wow is it right on theme. Especially BECAUSE you would expect to pass it over, and then you think about it and it’s right on target. For being truly unintentional (to me), it earns a vote. ', '2025-05-27T17:36:09Z'),
  (721, 134, 4, 1, 'This is phenomenal. It’s like a Flannery O’Connor story set to music. Fits the theme in that you really have to think outside the box to see the (then clearly) strong correlation, which is what I was hoping for this round. ', '2025-05-27T17:36:09Z'),
  (722, 136, 4, -1, 'On theme, but I just can’t stand his voice. ', '2025-05-27T17:36:09Z'),
  (723, 138, 4, 1, 'This is such a good entry. At first glance you might not think it, but the final line really says it all. I am definitely rewarding “unintentional” and this is definitely the most unintentional of them all, I thinks ', '2025-05-27T17:36:09Z'),
  (724, 139, 4, 0, 'This was great, and I liked it more than I expected, but like Judd’s submission I feel it leans a bit too far towards romantic (at least in my listen) ', '2025-05-27T17:36:09Z'),
  (725, 140, 4, 0, 'This is the first time a comment has swayed me. Great interpretation. Well chosen even though it wasn’t my fave ', '2025-05-27T17:36:09Z'),
  (726, 141, 4, 0, 'I like this read a lot, but for me this was a glancing shot off the theme instead of a direct hit ', '2025-05-27T17:36:09Z'),
  (727, 142, 4, 0, 'Also a great submission and idea, but one that just didn’t hit home fully for me. I do thing the line “after my picture fades” gets to the constancy of Christ’s love ', '2025-05-27T17:36:09Z'),
  (728, 135, 11, 0, 'If this song were in Italian it would be in the CL songbook (complimentary). Lyrically love it but musically it didn’t do it for me', '2025-05-27T17:59:32Z'),
  (729, 136, 11, -1, '100% Jesus coded lyrics but musically it’s giving “secular Christmas song” in a way that detracts from the lyrics imo', '2025-05-27T17:59:32Z'),
  (730, 137, 11, 0, 'It’s giving I still haven’t found what I’m looking for in a different font ', '2025-05-27T17:59:32Z'),
  (731, 138, 11, 0, 'Idk about you guys but ever since I first heard this song a few years ago it’s spoken to me of the particularity and intimacy of Jesus’s love for me. “I can’t hide from you like I hide from myself” got me crying in my Kia soul every time
(Also “You already hurt my feelings three times” is such a Peter moment)', '2025-05-27T17:59:32Z'),
  (732, 139, 11, 0, '“I crawl back into your open arms” got me. But up to that point it wasn’t really hitting as a Jesus song ¯\_(ツ)_/¯ ', '2025-05-27T17:59:32Z'),
  (733, 140, 11, 0, 'I do like the lyrics of this a lot but didn’t hit hard enough to be in my top 3', '2025-05-27T17:59:32Z'),
  (734, 141, 11, 1, 'There’s a reason this song is cliche/basic/enduringly popular. It refracts the human condition—the way we long to be loved—in a way that’s somehow both concrete and universally relatable (even if people don’t realize that this longing is only truly satisfied by God)', '2025-05-27T17:59:32Z'),
  (735, 142, 11, 1, 'I don’t think I realized until this listen just how much the lyrics could be about Jesus. And musically it has just the right blend of melancholy and consolation', '2025-05-27T17:59:32Z'),
  (736, 133, 11, 1, 'Perfect pick. Both because the song itself is perfect and because I can’t believe I didn’t realize until now just how perfectly it captures the Christian experience. I can’t believe this wasn’t already on my personal “songs about Jesus” playlist ', '2025-05-27T17:59:32Z'),
  (737, 134, 11, 0, 'I think I get where you’re trying to go with this one but it just doesn’t fully hit imo', '2025-05-27T17:59:32Z'),
  (738, 141, 8, 1, 'Sammybait, wisely chosen.', '2025-05-27T18:14:42Z'),
  (739, 133, 8, -1, 'Ah, you were successfully duped by the members of Evanescence into thinking that they aren''t a Christian band. This song is most intentionally about Jesus.', '2025-05-27T18:14:42Z'),
  (740, 134, 8, 0, 'Too explicitly religious in its grungled angels, discarded.', '2025-05-27T18:14:42Z'),
  (741, 135, 8, 0, 'Quit submitting songs I can''t understand, Judd.', '2025-05-27T18:14:42Z'),
  (742, 136, 8, 1, 'Someone profited from their reading of Paradiso Canto I.', '2025-05-27T18:14:42Z'),
  (743, 137, 8, 0, 'An unknowingly Christian song, yes, but it describes the longing more than Christ himself. I neither vote nor down vote you; I look on with compassionate disdain.', '2025-05-27T18:14:42Z'),
  (744, 138, 8, 1, 'Understood the assignment, as Joseph says.', '2025-05-27T18:14:42Z'),
  (745, 139, 8, 0, 'An incredible song. I loved it!', '2025-05-27T18:14:42Z'),
  (746, 140, 8, 0, 'Unfortunately, the tide has turned against explanatory captions.', '2025-05-27T18:14:42Z'),
  (747, 134, 3, 0, 'My ears just tune out Alexcore, I’m not capable of receiving it', '2025-05-27T18:49:03Z'),
  (748, 135, 3, 0, 'Chorus is actually really nice. I like the melody which is rare for Spanish songs', '2025-05-27T18:49:03Z'),
  (749, 136, 3, -1, NULL, '2025-05-27T18:49:03Z'),
  (750, 138, 3, 1, 'This song is definitely capturing something. Wish it were slightly more interesting but it’s close to being great ', '2025-05-27T18:49:03Z'),
  (751, 140, 3, 0, 'Wow, sweet sound although the thematic connection is a stretch. Love the shoegaze though ', '2025-05-27T18:49:03Z'),
  (752, 141, 3, 1, 'It fits', '2025-05-27T18:49:03Z'),
  (753, 142, 3, 1, 'I’m not excited about the song but the thematic connection is there', '2025-05-27T18:49:03Z'),
