  (1815, 299, 3, 1, 'This song has the most incredible energy and momentum. Wish I could sing it. Good choice Clara', '2025-08-02T18:43:34Z'),
  (1816, 290, 5, -1, 'I loved the reference, I think I would be unable to emotionally handle moving to this song... it would grate on me like 1 listen in. Big sad : (', '2025-08-02T20:23:19Z'),
  (1817, 292, 5, 1, 'Upvote for the creativity/the overall vibe created. I enjoyed.', '2025-08-02T20:23:19Z'),
  (1818, 294, 5, 1, 'Vibey. I appreciate this.', '2025-08-02T20:23:19Z'),
