INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (1901, 304, 9, 0, 'This is very BC, so imma guess Fiona or Shea', '2025-08-08T02:11:11Z'),
  (1902, 303, 11, -1, 'It’s a fine song but it just doesn’t scream Judd to me. But maybe this is just a side of his music taste that I have yet to discover', '2025-08-08T04:25:38Z'),
  (1903, 300, 11, 0, 'Agreed that lyrically this is on point, and I love that it riffs on the rebel soldier bit. Also agreed that I’m not sure it’s Juddcore musically speaking', '2025-08-08T04:25:38Z'),
  (1904, 301, 11, 1, 'This is so beautiful and I feel like he will dig. Jazzy but also folk vibes which kind of reminds me of some of Natalia Lafourcade’s stuff', '2025-08-08T04:25:38Z'),
  (1905, 302, 11, 0, 'This is so cute but it’s a little bit too poppy to make the podium for me. Maybe I’m underestimating Judd’s sentimental romantic side tho', '2025-08-08T04:25:38Z'),
  (1906, 304, 11, 0, 'It’s not quite the same thing but I feel like this might appeal to his Avett Brothers loving side?', '2025-08-08T04:25:38Z'),
  (1907, 305, 11, 1, '90s female fronted indie/alternative is pretty standard issue Juddcore', '2025-08-08T04:25:38Z'),
  (1908, 306, 11, 1, 'This one also feels quite squarely Juddcore. Perhaps I’m truly wildly off but this feels like something that either Eddie would submit for Judd or that Judd would submit for himself. (And if it’s not, then whoever did submit this should know that that’s a compliment)', '2025-08-08T04:25:38Z'),
  (1909, 307, 11, 0, 'I do feel like he’d like this. I also feel like he most likely already knows this song?', '2025-08-08T04:25:38Z'),
  (1910, 308, 11, 0, 'This is so cool. I honestly don’t have a great read on whether he’d love it though I think at the very least he will find it quite impressive', '2025-08-08T04:25:38Z'),
  (1911, 309, 11, 1, 'I was torn on this one, I feel like there’s a chance he’d be super into it but also a chance that it wouldn’t hit for whatever reason. I’m gonna go with yes. Judd can rock with some folksy Americana angst every now and then', '2025-08-08T04:25:38Z'),
  (1912, 310, 11, 0, 'Swedish Britpop just feels like a Judd vibe to me', '2025-08-08T04:25:38Z'),
