INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (2101, 329, 12, -1, 'My hand was forced, I didn''t want to, but the League had dirt on me.', '2025-08-16T19:38:15Z'),
  (2102, 323, 12, 1, NULL, '2025-08-16T19:38:15Z'),
  (2103, 328, 12, 2, NULL, '2025-08-16T19:38:15Z'),
  (2104, 325, 11, 0, 'I did not have another vote to give to this song but this one really hit for reasons that definitely don’t have anything to do with recent personal experience', '2025-08-16T20:03:32Z'),
  (2105, 326, 11, 1, 'Yeah this one really got me lyrically. Sometimes when you lose people it’s the little things that really get you, like seeing a random article of clothing like one they used to wear, or hearing a song that you absolutely know they’d love but not being able to share it with them. ', '2025-08-16T20:03:32Z'),
  (2106, 328, 11, 1, 'This song is just perfect musically as well as lyrically. Exactly the kind of song you and your friends sing along with at the top of your lungs because it’s so angsty but so unironically good, and that’s exactly the kind of memory you’ll look back on fondly after you’ve parted. Also this got me headbanging and finger pointing in my CA bedroom the second it came on which was a much needed serotonin hit in this time of transition', '2025-08-16T20:03:32Z'),
  (2107, 329, 11, 1, 'I loved this so much. It really gets at the bittersweet feeling of recognizing and holding together the seemingly contradictory emotions that occur during a period of transition—you can have an experience that utterly breaks your heart, and yet you still would never for a second wish it hadn’t happened. ', '2025-08-16T20:03:32Z'),
  (2108, 330, 11, -1, 'Perhaps controversial but this one gets the downvote for being extremely literally on theme. It’s still of course an amazing song and it fits the prompt perfectly. But in a round where I genuinely liked every song, I had to pick some criterion according to which to assign a downvote. Alas', '2025-08-16T20:03:32Z'),
  (2109, 331, 11, 1, 'Hard to really articulate why but this one just felt like the musical vibe fit perfectly with the lyrical/thematic content. Maybe this just betrays my own fondness for indie rock but idk. To me this song really captures that feeling you get when you know your days/hours with friends are numbered, so you start to feel sad and nostalgic even though the time isn’t actually up yet, and you have to fight to keep from wallowing in that angst so you can be fully present in the moment itself.', '2025-08-16T20:03:32Z'),
  (2110, 326, 2, 1, NULL, '2025-08-16T20:13:54Z'),
  (2111, 331, 2, 1, NULL, '2025-08-16T20:13:54Z'),
  (2112, 332, 2, 1, 'Wow this was awesome', '2025-08-16T20:13:54Z'),
  (2113, 324, 2, 1, 'Beautiful.', '2025-08-16T20:13:54Z'),
  (2114, 330, 2, -1, 'Too easy I’m sorry', '2025-08-16T20:13:54Z'),
