INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (2301, 360, 4, 1, 'I feel like this is a direct hit. Good tune, good vocals, just solid', '2025-09-20T17:27:48Z'),
  (2302, 368, 4, 1, 'I was back-and-forth on this one. In the end, I think it deserves a vote because it’s the musical style that I think really works, and even if Alex doesn’t agree with every part of the message, I think he would greatly enjoy the political themes.', '2025-09-20T17:27:48Z'),
  (2303, 367, 4, 0, 'Gotta dig deep for one that you know people haven’t heard', '2025-09-20T17:27:48Z'),
  (2304, 366, 4, 1, 'YES', '2025-09-20T17:27:48Z'),
  (2305, 364, 4, 0, 'I really like this song, and I like going for a vaguely classic rock angle, but I think this just misses the leaderboard', '2025-09-20T17:27:48Z'),
  (2306, 363, 4, 0, 'This is a runner-up for me. Like the sound, I think Alex would like it too, but it’s a little bit too whiny in the vocals imo ', '2025-09-20T17:27:48Z'),
  (2307, 362, 4, 0, 'This is SUCH a good pick tbh. Would never have thought about it, but the millennial vibe fits. But there is LITERALLY no one in these united states who has not heard this song. Cannot reward ', '2025-09-20T17:27:48Z'),
  (2308, 361, 4, 1, 'I LOVED this so much. I forget often that Taylor really deserves her fame and adulation. What a story and exactly in the vein of musical storytelling I think Alex likes ', '2025-09-20T17:27:48Z'),
  (2309, 359, 4, 0, 'This was so good, but I feel like Alex is pop-punk adjacent. Would have been a ringer for Claire round ', '2025-09-20T17:27:48Z'),
  (2310, 358, 4, 0, 'This is a good pick but I feel like Alex goes in more for the gravelly, melancholic folk (overall). A good choice but not a leaderboard choice for me ', '2025-09-20T17:27:48Z'),
  (2311, 357, 4, -1, 'Risqué…..bopping……

not exactly Alex’s top words 

