  (2422, 379, 4, 1, 'Proper use of the category ', '2025-09-27T22:51:21Z'),
  (2423, 378, 4, -1, 'THIS IS JUST A NORMAL SONG. ￼ and also the most popular of the normal songs posted hence the downvote.', '2025-09-27T22:51:21Z'),
  (2424, 369, 4, 0, 'THIS IS JUST A NORMAL SONG IN MONGOLIAN ', '2025-09-27T22:51:21Z'),
  (2425, 370, 4, 1, 'Don’t need to hear you out, already a banger. But a good choice for the category, hence its vote over the jelly one', '2025-09-27T22:51:21Z'),
