  (2566, 390, 5, 1, NULL, '2025-10-10T03:37:49Z'),
  (2567, 387, 12, 2, NULL, '2025-10-10T04:52:45Z'),
  (2568, 390, 12, -1, NULL, '2025-10-10T04:52:45Z'),
  (2569, 392, 12, 1, NULL, '2025-10-10T04:52:45Z'),
  (2570, 383, 12, 1, NULL, '2025-10-10T04:52:45Z'),
  (2571, 397, 6, 1, NULL, '2025-10-14T00:13:48Z'),
  (2572, 403, 6, 1, NULL, '2025-10-14T00:13:48Z'),
  (2573, 402, 6, -1, 'Real ones know this is Gen X not Millennial. ', '2025-10-14T00:13:48Z'),
  (2574, 401, 6, 2, NULL, '2025-10-14T00:13:48Z'),
  (2575, 400, 1, 0, 'No thoughts ', '2025-10-14T00:44:08Z'),
  (2576, 399, 1, -1, 'I actually hate this song. I can only listen to it if I make fun of it. The opening instrumental alone fills me with dread. And then the cursive singing… 😑 I decided to downvote because I hate it but it’s defs on theme sry ', '2025-10-14T00:44:08Z'),
  (2577, 398, 1, 0, 'I’m unaware of muse ', '2025-10-14T00:44:08Z'),
  (2578, 397, 1, 0, 'Our millennial chaplain in college loved his homily on this song and the beatitudes and st Francis. Not the most iconic Mumford song but one I generally like even now. And as we know I generally believe the subtitle matters even if I dont like it ', '2025-10-14T00:44:08Z'),
  (2579, 396, 1, 1, 'Hating this song? What sort of Grinch are you? I’m glad this album was included. I considered submitting Gale Song. You dont deserve the points for hating this but I must vote for it.', '2025-10-14T00:44:08Z'),
  (2580, 395, 1, 0, 'Nostalgia factor is nonexistent for me here ', '2025-10-14T00:44:08Z'),
  (2581, 394, 1, 1, 'I didn’t think of this and I could see how some may judge it as basic but this theme sort of implies nostalgic classics and I’ll never not bop to this. Might be my top pick of the non stomp clap possibilities for this round. (The movie About Time made me like this song even more!) it is the only one here that you could say “defined a generation” I would give it 2 votes if I didn’t like others as much as I do. Is this Sam? ', '2025-10-14T00:44:08Z'),
  (2582, 404, 1, 1, '🥲 there was a traumatizing skit from a retreat with this as the background song but it could never ruin it for me', '2025-10-14T00:44:08Z'),
  (2583, 403, 1, 0, 'fun. was a good shout. We translated “we are young” in high school Spanish hahah', '2025-10-14T00:44:08Z'),
  (2584, 402, 1, 0, 'Aww this one. Not enough votes ', '2025-10-14T00:44:08Z'),
  (2585, 401, 1, 1, 'Aww love the pitch perfect version too. Good pick.', '2025-10-14T00:44:08Z'),
  (2586, 402, 8, 0, 'A beautiful song, utterly intimate song writing. It got beat by others, but know that I treasured every second of it, and I hope others begin to see the life-changing joy of this song.', '2025-10-14T01:02:33Z'),
  (2587, 400, 8, 1, 'A really amazing song, and the only one on here I''d never heard before. It''s got a bit, it''s got piano, trumpets, what more can you ask for. It''s become my new obsession, thanks!', '2025-10-14T01:02:33Z'),
  (2588, 399, 8, 0, 'Mountain Sound or Numb Bears was the play', '2025-10-14T01:02:33Z'),
  (2589, 398, 8, 0, 'I like my Muse song better', '2025-10-14T01:02:33Z'),
  (2590, 397, 8, 0, 'Every one of their songs is the same lol', '2025-10-14T01:02:33Z'),
  (2591, 396, 8, -1, 'A genuinely awful song by a bad band. I know the subtitle might justify this pick, but I just can''t do it, I''m sorry', '2025-10-14T01:02:33Z'),
  (2592, 394, 8, 0, 'Catholic Communists at Hillsdale would be upset with me but I''ve never loved it, mostly because I associate it with pseudo-intellectual hedonism', '2025-10-14T01:02:33Z'),
  (2593, 404, 8, 1, 'There are other Coldplay songs I would''ve picked, but I said in chat that Coldplay was the right move for this round, and I''m gonna stand by it. Listening to this took me way back.', '2025-10-14T01:02:33Z'),
  (2594, 403, 8, 1, 'An awesome pick for the category. In case you didn''t know, the music video makes it into an American Civil War song, which changes the interpretation of the lyrics in really cool ways. Well done.', '2025-10-14T01:02:33Z'),
  (2595, 401, 8, 1, 'A masterful pick from an incredible album. ', '2025-10-14T01:02:33Z'),
  (2596, 403, 13, 0, 'It''s got the stomps
It''s got the claps
It''s got the Autotune
It''s got the falsetto
And Notre Dame''s Marching Band did it.

It''s a great song, and the best one for this category (besides maybe the M&S submission, which I had tried to do).', '2025-10-14T01:47:12Z'),
  (2597, 394, 13, 1, 'Garage Rock sound (check)
Overly Sappy and Whiny Lyrics (check)
Low Quality Synth (check)

I think this is the perfect 2005 song.  Therefore I grant it one upvote.', '2025-10-14T01:47:12Z'),
  (2598, 395, 13, 0, 'I think only Joseph would believe that Muse was "millennialcore" 

edit: Apparently there was another Muse song submitted... so I stand corrected.', '2025-10-14T01:47:12Z'),
  (2599, 396, 13, 0, 'This really captures the "stomp clap slop" part of the prompt.', '2025-10-14T01:47:12Z'),
  (2600, 397, 13, 1, 'I was warned not to submit another M&S song (Little Lion Man, which I think was a bigger hit).  I can''t not vote for this.', '2025-10-14T01:47:12Z');
INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (2601, 398, 13, 0, 'What?  A second Muse song?!  You people think too highly of Millennials'' music tastes.', '2025-10-14T01:47:12Z'),
  (2602, 399, 13, 1, 'No song embodies millennialcore more.', '2025-10-14T01:47:12Z'),
  (2603, 400, 13, 0, 'Great Song.  But I don''t think ', '2025-10-14T01:47:12Z'),
  (2604, 401, 13, -1, 'A catchy song from the Millennial era, but not something that embodies "millennialcore" or "stomp clap stop"', '2025-10-14T01:47:12Z'),
  (2605, 402, 13, 1, 'A little earlier Millennial... but It checks out. ', '2025-10-14T01:47:12Z'),
  (2606, 404, 13, 0, 'Just kidding this is Joseph''s submission', '2025-10-14T01:47:12Z'),
  (2607, 400, 3, 0, 'Total Bradcore. I actually love it, the screams are awesome!', '2025-10-14T02:11:48Z'),
  (2608, 399, 3, 1, 'Musical torment. The indie voices. The “hey”s drowned in reverb. The boring chord progression beaten to death and beyond. This is the ultimate millenialcore', '2025-10-14T02:11:48Z'),
  (2609, 394, 3, 1, 'Hard to argue. A shame that this is their only good song (that I’ve heard)', '2025-10-14T02:11:48Z'),
  (2610, 395, 3, -1, 'Glorious. What a wonderful musical journey. I love how the French part feels like a totally different world to the rest of the song and then they bring it back into main song, it’s very effective and unique. I sang along to this in the car like a total goofball. This was legit one of my favorite songs in college, when I was obsessed with Muse. Unfortunately, this is not millennialcore in any sense except being by a band active during peak millennial years', '2025-10-14T02:11:48Z'),
  (2611, 396, 3, 0, 'This is truly an awful song as you say. I feel that it was beat out by little talks which is even worse and more obnoxious. What people see in this band I fail to fathom. I played this one with my college band', '2025-10-14T02:11:48Z'),
  (2612, 398, 3, 0, 'Another great muse song, but not iconic enough or famous enough to really typify the era. I used to not listen to this one because they say F, guess my standards went down the drain', '2025-10-14T02:11:48Z'),
  (2613, 397, 3, 0, '😴 yawnfest but not as egregious as little talks which wins in this lane of millennialcore for me. ', '2025-10-14T02:11:48Z'),
  (2614, 403, 3, 1, 'Wow, this song is actually quite interesting and creative. While it does feature the obligatory millennial “ohhhhh ohhh ohhh ohhhh” singalong bit, this song takes many unexpected turns while still feeling cohesive and distinctive. The guy has a super cool voice too. No idea what it’s about but it sounds important', '2025-10-14T02:11:48Z'),
  (2615, 402, 3, 1, 'This is a great song and feels iconic enough to be millenialcore ', '2025-10-14T02:11:48Z'),
  (2616, 396, 9, 1, NULL, '2025-10-15T12:31:58Z'),
  (2617, 395, 9, 1, 'I vibe with this!', '2025-10-15T12:31:58Z'),
  (2618, 404, 9, 0, 'Wish I had another upvote for this', '2025-10-15T12:31:58Z'),
  (2619, 403, 9, 1, NULL, '2025-10-15T12:31:58Z'),
  (2620, 400, 9, -1, 'I didn’t absolutely hate it, but I needed to downvote something ', '2025-10-15T12:31:58Z'),
  (2621, 398, 9, 0, 'Do I detect a hint of superstition??', '2025-10-15T12:31:58Z'),
  (2622, 397, 9, 1, NULL, '2025-10-15T12:31:58Z'),
  (2623, 399, 11, 0, 'My apologies to whoever submitted this, it’s absolutely a valid read of the theme, it’s just (imo) a predictable and not particularly exciting pull ', '2025-10-16T04:51:34Z'),
  (2624, 398, 11, 0, 'Not at all complaining about two Muse picks. So good. The other one just hit more', '2025-10-16T04:51:34Z'),
  (2625, 397, 11, 0, 'cf. my comments on little talks and Ophelia. It’s an enjoyable song though', '2025-10-16T04:51:34Z'),
  (2626, 396, 11, 0, 'It’s okay if not everyone agrees with my voting rationale, but stereotypical/predictable stomp clap bands just won’t wow me enough to claim an upvote', '2025-10-16T04:51:34Z'),
  (2627, 395, 11, 1, 'Twilight soundtrack = automatic upvote. It doesn’t get much more millenialcore than that. Also just genuinely incredible soundtracks ', '2025-10-16T04:51:34Z'),
  (2628, 394, 11, 0, 'Was torn on this one. On the one hand, it’s a pretty predictable/mainstream pick. On the other hand, this song played at a wedding reception has the power to activate the sleeper agent inside every millennial and make them jump up and down with reckless abandon. In the end it was narrowly edged of my top 4, but thank you, to whoever submitted this, for the massive serotonin hit that I got from hearing the opening guitar riff. Never fails', '2025-10-16T04:51:34Z'),
  (2629, 404, 11, 1, 'The first Coldplay song my mind went to for this round was viva la vida. But I grew to like this particular pick because I feel like sonically it hits all the hallmarks of 2000s alt/rock, but in an authentic (rather than derivative) way.

(Hi Joseph)', '2025-10-16T04:51:34Z'),
  (2630, 403, 11, 1, 'This album is one of a kind and this song is just so good. Stomp clap folk drumbeats AND vocoder bridge? I repeat my comment from last round: Jack Antonoff knows how to write a pop song. Every now and then I wonder what fun. could have become if they’d stayed together', '2025-10-16T04:51:34Z'),
  (2631, 402, 11, -1, 'This one is for sure beloved by millennials but chronologically feels a little early for the category imo', '2025-10-16T04:51:34Z'),
  (2632, 401, 11, 0, 'This whole album is so good and the lineup of features is next level. Idk what it is about B.o.B’s particular brand of upbeat pop rap but it feels like the sort of thing that only would’ve landed with the impact it did at this particular point in musical history ', '2025-10-16T04:51:34Z'),
  (2633, 400, 11, 1, 'The dog barking thing is weird as hell but it made me think to myself “2010 is the only possible time in history this could’ve worked.” Looked up the release year and sure enough, 2010. And the bright poppy piano and horns with the driving beat are delightfully 2010 as well. Even the guitar solo and tone just scream this time period. Cool pick, and I respect the choice to go with something less mainstream 

(Hi Eddie)', '2025-10-16T04:51:34Z'),
  (2634, 404, 5, 1, NULL, '2025-10-18T01:44:34Z'),
  (2635, 403, 5, 1, NULL, '2025-10-18T01:44:34Z'),
  (2636, 401, 5, 1, NULL, '2025-10-18T01:44:34Z'),
  (2637, 399, 5, 1, NULL, '2025-10-18T01:44:34Z'),
  (2638, 396, 5, -1, 'I love this song... but, hot take, I think it''s more Gen Z than Millennial 😬😬😬 Released 2016', '2025-10-18T01:44:34Z'),
  (2639, 401, 2, 0, 'I was surprisingly impressed by this. Honorable mention. It’s hitting a particular corner of the millennial slop genre that the rest of the playlist doesn’t cover ', '2025-10-18T03:12:28Z'),
  (2640, 403, 2, 1, 'To my mind, this is the definitive entry in the genre ', '2025-10-18T03:12:28Z'),
  (2641, 404, 2, -1, 'There are really no bad entries on this playlist, but this one felt the least fitting to me', '2025-10-18T03:12:28Z'),
  (2642, 400, 2, 1, 'This was extremely fun', '2025-10-18T03:12:28Z'),
  (2643, 395, 2, 1, 'I had never heard this before, I really liked it ', '2025-10-18T03:12:28Z'),
  (2644, 397, 2, 1, 'lmao. Essential', '2025-10-18T03:12:28Z'),
  (2645, 399, 4, 1, NULL, '2025-10-18T04:07:27Z'),
