  (2689, 408, 10, 1, NULL, '2025-10-24T20:54:42Z'),
  (2690, 409, 10, 1, NULL, '2025-10-24T20:54:42Z'),
  (2691, 412, 10, 1, NULL, '2025-10-24T20:54:42Z'),
  (2692, 411, 3, 1, 'This probably made me feel the saddest of anything here. So cute and sad', '2025-10-24T21:03:21Z'),
  (2693, 412, 3, 0, 'This was a great song, but theme connection is not the strongest. The implications are there though', '2025-10-24T21:03:21Z'),
  (2694, 413, 3, 0, 'Compelling and haunting ', '2025-10-24T21:03:21Z'),
  (2695, 414, 3, -1, 'Musical fingernails on chalkboard. The melodies don’t work and everything is irritating, this song feels like a itchy dress shirt or a bathing suit with sand in it', '2025-10-24T21:03:21Z'),
  (2696, 405, 3, 0, 'This was very pretty ', '2025-10-24T21:03:21Z'),
  (2697, 406, 3, 0, 'Dang, that was very compelling. Country is a perfect genre for this theme as many people clearly agree', '2025-10-24T21:03:21Z'),
  (2698, 408, 3, 1, 'Holy cow what was this. Incredible ', '2025-10-24T21:03:21Z'),
  (2699, 409, 3, 1, 'Can’t not vote for Sufjan. This just sounds so vulnerable and raw like everything on this album. ', '2025-10-24T21:03:21Z'),
  (2700, 410, 3, 1, 'Perhaps the clearest and best interpretation of the theme here', '2025-10-24T21:03:21Z');
INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (2701, 407, 11, 1, 'Enjoyed this pull. This is also how I learned that Spotify censors the n word in its lyrics (assuming this is Alex but perhaps Sam??)', '2025-10-25T03:20:09Z'),
  (2702, 406, 11, 1, 'This song is really haunting and cool musically as well as lyrically. The way that, in this song, a very specific manner/place of death is inescapable no matter how you may try to run away feels like an image or perhaps a microcosm of the more universal reality that it is inescapable for all of us', '2025-10-25T03:20:09Z'),
  (2703, 408, 11, 1, 'At first I thought this song was gonna be kinda corny but by the end I did quite enjoy the picture it painted lyrically ', '2025-10-25T03:20:09Z'),
  (2704, 409, 11, 0, 'Fiona has the receipts but I told her before this round that if somebody submitted Sufjan it would be the first time in music league history that I didn’t vote for him. I just feel like it’s too easy. Also despite the line “we’re all gonna die,” I feel like this song is more properly about the experience of his mother’s death rather than reflecting on his own mortality ', '2025-10-25T03:20:09Z'),
  (2705, 410, 11, 0, 'At first I was like “this is so spot on” but as I was reflecting on all the songs again I felt like the vibe of this one is more about God’s judgment catching up with the sinner than about the inevitability of death for all. I’d apologize for being nitpicky but I feel like that’s what music league is for', '2025-10-25T03:20:09Z'),
  (2706, 411, 11, 1, 'Is it possible that I voted for this in part because I love Noah Kahan’s music and also because he just has fall vibes? Sure. But it’s also on point thematically', '2025-10-25T03:20:09Z'),
  (2707, 412, 11, -1, 'Respectfully, being haunted by the ghost of Hank Williams just isn’t the same as confronting your mortality imo', '2025-10-25T03:20:09Z'),
  (2708, 415, 11, 0, 'Joseph I did think this was cool, but it did not make my top 4 alas', '2025-10-25T03:20:09Z'),
  (2709, 410, 8, 1, NULL, '2025-10-25T03:22:00Z'),
  (2710, 412, 8, 2, NULL, '2025-10-25T03:22:00Z'),
  (2711, 413, 8, 1, NULL, '2025-10-25T03:22:00Z'),
