INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (3501, 500, 11, 1, 'Thought about submitting this one. American Idol in the aughts was such a beautiful cultural moment', '2025-12-04T22:22:48Z'),
  (3502, 501, 11, 0, 'Hell yeah this song is so good. It pains me to not vote for Bilmuri but I didn’t feel like it was in the top 4 for the theme', '2025-12-04T22:22:48Z'),
  (3503, 502, 11, 0, 'This song is great. I don’t feel like it perfectly fits the theme though bc even though he’s recognizing the futility of his efforts this far, he’s still trying—there’s some sense of hope, or at least some commitment, that suggests it is not in fact over ', '2025-12-04T22:22:48Z'),
  (3504, 506, 11, 1, 'Incredible pull for this category', '2025-12-04T22:22:48Z'),
  (3505, 507, 11, -1, 'Good song but it’s not sufficiently giving “over” imo. Realizing things aren’t the way you thought they were =/= it being so over. More like a new start', '2025-12-04T22:22:48Z'),
  (3506, 508, 11, 1, 'This song is so good holy cow. And it fits the theme both lyrically and sonically ', '2025-12-04T22:22:48Z'),
  (3507, 510, 11, 0, 'Enjoy the song and the ironic ending but this one also isn’t sufficiently giving “over”', '2025-12-04T22:22:48Z'),
  (3508, 511, 11, 0, 'Oh my gosh this is cool. I haven’t had a chance to see the movie yet but it’s getting me even more pumped. It’s also a good read of the theme imo, didn’t have enough votes tho', '2025-12-04T22:22:48Z'),
  (3509, 512, 11, 1, 'Key changes oh my. Full disclosure this song annoyed me for the first few minutes, but the way it builds and just gets more and more manic really creates the despairing vibe. Begrudgingly feel like it earned my vote ', '2025-12-04T22:22:48Z'),
