  (3791, 540, 4, 0, 'This is a runner-up for sure. I haven’t heard this in at least 10 years, and I forgot how good it actually is. ', '2026-01-17T22:46:57Z'),
  (3792, 551, 4, 0, 'Honorable mention as runner-up. I like this one a lot, and it would be playing in a good diner. ', '2026-01-17T22:46:57Z'),
  (3793, 550, 4, 0, 'See comment above on 50s/60s songs for diners', '2026-01-17T22:46:57Z'),
  (3794, 549, 4, 1, 'Similar to Alex’s song, this one gets a vote because it both encapsulates what is most beautiful about what the diner represents, and it also sounds like something that would be playing in one', '2026-01-17T22:46:57Z'),
  (3795, 548, 4, 0, 'Guys…I don’t think they’re talking about food', '2026-01-17T22:46:57Z'),
  (3796, 547, 4, 0, 'As mentioned above, definitely likely to be playing in a diner. Great submission, but not getting a vote for the reasons mentioned above.', '2026-01-17T22:46:57Z'),
  (3797, 546, 4, 0, '"And they hadn''t noticed the magic."', '2026-01-17T22:46:57Z'),
  (3798, 545, 4, 0, 'Sorry for the treatise (that’s a lie. I’m not sorry.) this song to me makes me think of the faux 1950s/60s diners that seek to freeze forever in resin a specific time period in America so that they can hoover up the vast surplus wealth of the boomers. The 50s and 60s diner might be iconic, but the diner is a living breathing institution. When I hear this, it just makes me think of cashing in on real American culture.', '2026-01-17T22:46:57Z'),
  (3799, 544, 4, 0, 'Great song, and I get where you’re coming from, but didn’t stand out', '2026-01-17T22:46:57Z'),
  (3800, 543, 4, 0, 'Richard, you were so close with this. I have to say, this, carry on my wayward , and the Dolly Parton song are the ones I think might be most likely to be playing in a diner. But my votes were based on the songs I think best encapsulate the feel of a diner.', '2026-01-17T22:46:57Z');
INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (3801, 542, 4, 1, 'The diner is the prism of America. This song makes me think of what I love about them. Well done Alex.', '2026-01-17T22:46:57Z'),
  (3802, 541, 4, -1, 'Joseph, I would be tempted to vote for this if it was a meta critique on the fact that the working class people of America most likely to frequent the remaining real diners might actually be more drawn to this type of music. But I feel like you just wanted to submit it lol', '2026-01-17T22:46:57Z'),
  (3803, 539, 4, 1, 'To me, this is the song that best encapsulates the feel of actually being at a diner at the perfect moment for all the possible emotions it can create. A calm early morning, late night, feeling all the humanity of the people around you radiating out in all their goodness and brokenness. Long live the diner.', '2026-01-17T22:46:57Z'),
  (3804, 541, 9, -1, NULL, '2026-01-18T02:14:16Z'),
  (3805, 544, 9, 1, NULL, '2026-01-18T02:14:16Z'),
  (3806, 547, 9, 0, 'Not quite diner-core for me, but I love this song', '2026-01-18T02:14:16Z'),
  (3807, 551, 9, 1, NULL, '2026-01-18T02:14:16Z'),
  (3808, 539, 9, 1, NULL, '2026-01-18T02:14:16Z'),
  (3809, 547, 13, 0, 'Goes a little too hard for diner core.', '2026-01-18T03:24:06Z'),
  (3810, 550, 13, 1, '50''s music is a shortcut to winning at diner core', '2026-01-18T03:24:06Z'),
  (3811, 548, 13, 1, 'thematically and stylistically on point', '2026-01-18T03:24:06Z'),
  (3812, 539, 13, 0, 'I can definitely imagine myself sipping coffee while this plays through the grainy speaker barely audible over local news.', '2026-01-18T03:24:06Z'),
  (3813, 540, 13, 1, 'A very nice pick.  Definitely shows the devotion of a man to his local diner.  Well done.', '2026-01-18T03:24:06Z'),
  (3814, 541, 13, 0, 'I could imagine the one highschooler who works in the kitchen playing this.  Also I''m not sure I''d patronize a diner that has touchtunes.', '2026-01-18T03:24:06Z'),
