  (3859, 563, 4, 0, 'Alex, I applaud and respect you for this', '2026-01-22T03:36:48Z'),
  (3860, 552, 3, 0, 'In all honesty this deserves a vote but there aren’t enough. Regina would bop for sure', '2026-01-23T01:31:12Z'),
