INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (4101, 598, 15, 1, NULL, '2026-02-09T21:04:01Z'),
  (4102, 593, 11, 1, 'This feels like an Eddie pick. Totally fits that genre ', '2026-02-10T18:12:57Z'),
  (4103, 594, 11, -1, 'I am kind of obsessed with this song. Was in Chicago last week and thought to myself "it''s crazy how accurately Djo was able to capture what I''m feeling right now in a song." That being said, while I see how musically this has kind of a “roll credits” sound, I feel like lyrically/emotionally it’s something that’s not quite an end of movie feeling. It’s not an optimistic “new beginning” feeling, nor is it a poignant tragic feeling, so much as a melancholy but ultimately peaceful reflective feeling. Idk. A long winded way of saying I love the song but it didn’t feel right for the prompt', '2026-02-10T18:12:57Z'),
  (4104, 595, 11, 1, 'This feels like the sort of song that will get picked for movie credits because of its vaguely uplifting energy and lyrics but which will never have commercial success beyond that. The band will probably still have some success on the county fair circuit. Maybe play a set at four winds field sponsored by ND idea week. A respectable read of the category ', '2026-02-10T18:12:57Z'),
  (4105, 596, 11, 0, 'This was my honorable mention. Thematically it fits this very specific movie concept perfectly. I’m envisioning Mike Whitman appearing as many different characters who are not canonically related to one another whatsoever, but no one’s sure whether it’s just a bit or has some deep mystical significance', '2026-02-10T18:12:57Z'),
  (4106, 600, 11, 1, 'I dig it. Great song and I can totally see it being used in this way. The opening chords as the camera pans from the main character out to some nice panoramic shots before everything fades to black', '2026-02-10T18:12:57Z'),
  (4107, 589, 3, 1, 'This really hits. After the right film, could be extremely effective', '2026-02-10T21:22:36Z'),
  (4108, 590, 3, 0, 'I can’t picture when it would cut to black in this song. Intro is way too long', '2026-02-10T21:22:36Z'),
  (4109, 591, 3, -1, NULL, '2026-02-10T21:22:36Z'),
  (4110, 592, 3, 0, 'Not quite', '2026-02-10T21:22:36Z'),
  (4111, 593, 3, 1, 'This totally works. Painful nostalgia', '2026-02-10T21:22:36Z'),
  (4112, 594, 3, 0, 'The beginning of this just wouldn’t work in a film. But there is something really sweet about this! ', '2026-02-10T21:22:36Z'),
  (4113, 595, 3, 0, 'Sounds like it would play after a terrible marvel movie', '2026-02-10T21:22:36Z'),
  (4114, 596, 3, 0, 'I see the vision', '2026-02-10T21:22:36Z'),
  (4115, 598, 3, 1, 'Great somber ending to a film. Would leave thoughtful and wistful', '2026-02-10T21:22:36Z'),
  (4116, 599, 3, 0, 'Sorry Peter, I’m not crazy about this', '2026-02-10T21:22:36Z'),
  (4117, 589, 2, 1, 'No notes. John Hughes core 80s/90s coming of age type stuff ', '2026-02-10T23:04:46Z'),
  (4118, 590, 2, 1, 'Initially I was gonna pass this one over because it takes too long for the hook to arrive, I think an essential feature of the end credits track is that the hook drops in exactly with the fade to black; too much build up ruins it. However I realized many other submissions did something similar, as though the final scene plays through the first 30 seconds or so and the fade to black drops in at like 0:39. Graded on that curve, this becomes one of the standouts I think', '2026-02-10T23:04:46Z'),
  (4119, 591, 2, -1, 'One of my all time favorite songs, but this has more of a beginning than an ending feel to me ', '2026-02-10T23:04:46Z'),
  (4120, 593, 2, 0, 'I forgot this song existed, thank you for the reminder. Millennialcore throwback ', '2026-02-10T23:04:46Z'),
  (4121, 595, 2, 1, 'This song is steaming garbage but I am duty bound to admit that it’s a perfect submission. It practically conjures the end credits scene of an aggressively mid action/kids movie on its own, title cards bearing Ryan Reynolds’ and Jeff Bridges’ names careening by as it plays ', '2026-02-10T23:04:46Z'),
  (4122, 596, 2, 0, 'I am picturing Peter Seeley appearing multiple times as different and seemingly unrelated characters encountered along the journey, without explanation', '2026-02-10T23:04:46Z'),
  (4123, 599, 2, 0, 'I enjoyed this ', '2026-02-10T23:04:46Z'),
  (4124, 600, 2, 0, 'Never thought of this as an end credits song but seeing it in this context, I realize it’s been here all along', '2026-02-10T23:04:46Z'),
  (4125, 589, 13, 1, 'Didn''t care that much for the song other than the first few seconds which would be perfect at the end of a movie.', '2026-02-11T00:45:42Z'),
  (4126, 591, 13, 0, 'This song seems so weak when I listen to the others.  Good job guys.', '2026-02-11T00:45:42Z'),
  (4127, 592, 13, 0, 'Not the ending you were hoping for, but the guy is okay with the girl walking away, and this plays.', '2026-02-11T00:45:42Z'),
  (4128, 593, 13, 0, 'I was going to downvote this until I saw "indie coming of age."', '2026-02-11T00:45:42Z'),
  (4129, 594, 13, 0, 'I could see this coming more ', '2026-02-11T00:45:42Z'),
  (4130, 595, 13, 0, 'I don''t think I really saw this as a strong movie ending, to be honest. ', '2026-02-11T00:45:42Z'),
  (4131, 596, 13, 1, 'Eddie and Judd are moving along the railroad on one of those hand crank railcarts for their last 38 miles toward the novitiate.

Recovering Alcoholic Richard finishes his first round of an intended several at the bar and as he reaches into his wallet but finds his polaroid from those goons.  Checks out his tab and stares up at the stars in wonder outside the bar.

A picture of Eddie and Judd that they had taken with their polaroid falls out of an epicurean Regina''s purse.  She smiles as she remembers those holy fools and sends a text to cancel her morally questionable meetup later that day.

Tech bro brad thinking about microdosing on LSD again this evening.  AI generated recap of the week hits his inbox, with a verbal description of the polaroid. He goes looking for it, and finds something from his childhood along the way, and stops and thinks.
', '2026-02-11T00:45:42Z'),
  (4132, 598, 13, 0, '"it was just like a movie" is an interesting line for a movie ending song. I like it.', '2026-02-11T00:45:42Z'),
  (4133, 599, 13, -1, 'This was the hardest sell as a movie closer. ', '2026-02-11T00:45:42Z'),
  (4134, 600, 13, 1, 'Great pull.  As soon as the singing starts it changes to black.  I can see it perfectly.', '2026-02-11T00:45:42Z'),
  (4135, 590, 9, 1, 'I don’t think I’ve ever listened to an entire song of The Who… I really enjoyed this!', '2026-02-11T02:24:35Z'),
  (4136, 592, 9, 1, 'Really loved this song🥰', '2026-02-11T02:24:35Z'),
  (4137, 596, 9, -1, 'I HATE that I’m downvoting this because I love the OP’s comment, but this one I think felt the least like an end credits song to me…
In my mind, this is the song that’s playing during the montage of scenes in which Eddie and Judd are traveling and ministering.', '2026-02-11T02:24:35Z'),
