  (4598, 655, 13, 0, '"God, help me leave the life of a big bag baller making big ass checks, but not yet" -Augustine, Probably', '2026-03-12T22:15:34Z'),
  (4599, 658, 13, 1, '"And see, you were within and I was in the external world and sought you there"  Well done.', '2026-03-12T22:15:34Z'),
