INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (4601, 660, 13, 0, 'Eh,  This isn''t really *accidentally* St. Augustine.  It''s pretty intentionally theological.', '2026-03-12T22:15:34Z'),
  (4602, 661, 13, 1, '"F****n magnets how do they work?" -Augustine, Probably

Upvote for creativity and cleverness', '2026-03-12T22:15:34Z'),
  (4603, 663, 13, 0, 'What a great song. "last call for sin"', '2026-03-12T22:15:34Z'),
  (4604, 664, 13, 1, 'Man, why you gotta bring Monica into this 😭😭  This is a really good take.', '2026-03-12T22:15:34Z'),
  (4605, 665, 13, 1, 'Man this song is so freakin good.  And a little cryptic, but I''ll choose to interpret it in a way that jibes w/ Augustine.', '2026-03-12T22:15:34Z'),
  (4606, 666, 13, -1, 'I''m guessing this is Richard''s submission b/c he couldn''t think of anything else.', '2026-03-12T22:15:34Z'),
  (4607, 654, 3, 1, 'I was going back and forth on this. I’ve concluded it’s almost but not quite. Good pull still', '2026-03-13T11:58:08Z'),
  (4608, 656, 3, 0, 'The read is not clear for me', '2026-03-13T11:58:08Z'),
  (4609, 657, 3, 0, 'Yes, this is a core Augustine theme. But there’s really just one line in this that connects. ', '2026-03-13T11:58:08Z'),
  (4610, 658, 3, 0, 'St. Augustine would not be down for this level of eastern mysticism ', '2026-03-13T11:58:08Z'),
  (4611, 659, 3, 0, 'This is just much easier to read as a breakup song than Augustine vibes ', '2026-03-13T11:58:08Z'),
  (4612, 660, 3, 0, 'Little vague to fit the theme. It’s impressive that Paul Simon doesn’t sound totally past his sell by date in 2011', '2026-03-13T11:58:08Z'),
  (4613, 661, 3, 0, 'Can’t comment on how great of a read this is but I get a kick out of the song. ', '2026-03-13T11:58:08Z'),
  (4614, 662, 3, -1, 'This is a great song, but not sold on the connection', '2026-03-13T11:58:08Z'),
  (4615, 663, 3, 1, 'I don’t love the killers, but this is a convincing read', '2026-03-13T11:58:08Z'),
  (4616, 664, 3, 0, 'Almost', '2026-03-13T11:58:08Z'),
  (4617, 665, 3, 2, 'Yes yes yes! This is spot on. “There’s no returning to the spoils once you’ve spoiled the thought of them.” This song can so easily be read as a song of conversion. There’s really not a single line that doesn’t fit. ', '2026-03-13T11:58:08Z'),
  (4618, 666, 3, 0, '*Pears

This was a fun closer', '2026-03-13T11:58:08Z'),
  (4619, 654, 6, 0, '
', '2026-03-13T20:04:11Z'),
  (4620, 655, 6, -1, 'Feels like this would be more appropriate for a martyr ', '2026-03-13T20:04:11Z'),
  (4621, 661, 6, 1, 'Voted despite the comment. ', '2026-03-13T20:04:11Z'),
  (4622, 662, 6, 1, NULL, '2026-03-13T20:04:11Z'),
  (4623, 664, 6, 1, NULL, '2026-03-13T20:04:11Z'),
  (4624, 665, 6, 1, NULL, '2026-03-13T20:04:11Z'),
  (4625, 654, 2, 0, 'This song strikes me as more generically “accidentally about Jesus” than accidentally about Augustine ', '2026-03-13T23:52:53Z'),
  (4626, 655, 2, 1, 'I loved this song being on this playlist but the lyrics just didn’t cry “Augustine” to me as much as I was hoping they would. As with a few others, it seems to be more about conversion in general. But with that said it stood ahead of some others in that category and for just being really fun and unexpected I feel compelled to upvote.', '2026-03-13T23:52:53Z'),
  (4627, 656, 2, 0, 'Maybe I got completely filtered by this. I’m just not sure there’s really enough to go on here ', '2026-03-13T23:52:53Z'),
  (4628, 657, 2, 1, 'flawless. Great pick', '2026-03-13T23:52:53Z'),
  (4629, 661, 2, 0, 'Kinda clever, I especially enjoy really tonally discordant/unexpected picks for these rounds. That said, I apologize for not being an Augustinian scholar but the deeper cut reference didn’t hit as hard for me ', '2026-03-13T23:52:53Z'),
  (4630, 662, 2, 0, 'I don’t get it ', '2026-03-13T23:52:53Z'),
  (4631, 664, 2, 1, 'I loved this. Great song and interesting read of the category ', '2026-03-13T23:52:53Z'),
  (4632, 665, 2, 1, 'I have loved this song and this album for a long time, very nostalgia inducing, and this is a cool new way for me to interpret the lyrics. Awesome fit for the category ', '2026-03-13T23:52:53Z'),
  (4633, 666, 2, -1, 'Not about pears. (Awesome song tho)', '2026-03-13T23:52:53Z'),
  (4634, 654, 11, 0, 'I see the vision and obviously all human love images the love God has for us but I feel like this is a bit too clearly about a human couple to work for me', '2026-03-14T01:48:47Z'),
  (4635, 655, 11, 1, 'Fun pull. I read this as pre conversion Augustine struggling to remain in denial about the emptiness of the life he’s chosen
(Hi Joseph) ', '2026-03-14T01:48:47Z'),
  (4636, 656, 11, -1, 'Maybe this is a me problem but this song just has too much of a woo woo new agey “spiritual discovery” vibe to work as an Augustine song for me', '2026-03-14T01:48:47Z'),
  (4637, 657, 11, 0, 'This is accurate for sure. Less about Augustine himself and more about a universal phenomenon that he articulated. Perfectly valid read but didn’t quite make podium for me', '2026-03-14T01:48:47Z'),
  (4638, 658, 11, 0, 'Yes God is within him, but also Heaven and earth are crying out that they were made by God?', '2026-03-14T01:48:47Z'),
  (4639, 659, 11, 0, 'This was one of the more loosely Augustinian submissions imo. I liked the song well enough though', '2026-03-14T01:48:47Z'),
  (4640, 660, 11, 0, 'The hook is giving Augustine but the rest of the song not so much? It feels like there are a few lines that are spoken from the pov of God? Idk. Didn’t quite land for me and was eclipsed by the other Paul Simon submission', '2026-03-14T01:48:47Z'),
  (4641, 661, 11, 1, 'Made me think of the part in city of God where he talks about salamanders who live in fire. Also
“Music is all magic
You can''t even hold it
It''s just there in the air
Pure motherfucking magic”
is basically just a line from book X of the confessions', '2026-03-14T01:48:47Z'),
  (4642, 662, 11, 0, 'Is this meant to be Augustine pre conversion? I can kinda see it', '2026-03-14T01:48:47Z'),
  (4643, 663, 11, 0, 'Smells like Eddie. Incredible song. Narrowly missed my top 4', '2026-03-14T01:48:47Z'),
  (4644, 664, 11, 1, 'Can’t not vote for this one, too spot on', '2026-03-14T01:48:47Z'),
  (4645, 666, 11, 1, 'As soon as I saw this on the list I knew it was an upvote. I’ve considered this song for a few past categories but this is a worthy round in which to use it', '2026-03-14T01:48:47Z'),
