INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (4701, 676, 4, 0, 'I could understand Mr. Harvey perfectly well, thank you very much', '2026-03-17T17:37:25Z'),
  (4702, 677, 4, 1, 'Mmmmm that''s good millennial slop. No idea what they''re talking about but I love it. ', '2026-03-17T17:37:25Z'),
  (4703, 678, 4, 0, 'I thought I knew what they''re saying but realized it was really only like 2 lines in the chorus. Not a single clue about the rest of it. ', '2026-03-17T17:37:25Z'),
  (4704, 670, 15, 1, NULL, '2026-03-17T23:55:44Z'),
  (4705, 668, 15, -1, 'A brilliant song, with clear vocals and meaning. The fact that the language is constructed does not make it "unintelligible". Alas, like Commodus , I must give the thumbs down to this noble work.', '2026-03-17T23:55:44Z'),
  (4706, 679, 15, 0, 'I feel gay just listening to this (and not in a fun way). Alas, I don''t have enough down votes.', '2026-03-17T23:55:44Z'),
  (4707, 678, 15, 1, 'I don''t ever remember it being so bad on the radio. Truly mumblesome. Absolutely terrible vocal clarity. Love it.', '2026-03-17T23:55:44Z'),
  (4708, 676, 15, 0, 'Clever gambit Joe, submitting your own song. ', '2026-03-17T23:55:44Z'),
  (4709, 671, 15, 2, 'Couldn''t understand a word he says, but we surely had a mighty fine time.', '2026-03-17T23:55:44Z'),
  (4710, 669, 15, 0, 'I listened to this backwards and I got a message from Satan: "song longer hell. Real Alex dead. buy bitcoin".', '2026-03-17T23:55:44Z'),
  (4711, 676, 13, 0, 'Very decipherable.', '2026-03-18T00:53:15Z'),
  (4712, 668, 13, 0, 'I mean it''s cool, and kinda gimmicky which I usually go for.  But I think it misses the point of the round.', '2026-03-18T00:53:15Z'),
  (4713, 669, 13, 0, 'There''s a great scene in the simpsons that makes fun of this, and they change it to "In the garden of eden, baby"

So I guess what I''m trying to say is that simpsons did it.

But this song is very intelligible. And it''s also very long.', '2026-03-18T00:53:15Z'),
  (4714, 670, 13, 1, 'alt-J is an easy upvote in this category.', '2026-03-18T00:53:15Z'),
  (4715, 671, 13, 1, 'Really enjoyed this one and could also not understand it at all. Upvote.', '2026-03-18T00:53:15Z'),
  (4716, 673, 13, 0, 'I feel like a big part of the reason you can''t hear this one is b/c of bad mixing, not because of mumbly singer.', '2026-03-18T00:53:15Z'),
  (4717, 674, 13, -1, 'This might be the worst song I''ve ever heard.  Katie made me change it before it finished.', '2026-03-18T00:53:15Z'),
  (4718, 675, 13, 1, 'Really fun song.  Couldn''t understand a word.', '2026-03-18T00:53:15Z'),
  (4719, 677, 13, 1, 'I was tapping my foot while listening to this song.  Couldn''t understand a word.', '2026-03-18T00:53:15Z'),
