  (4875, 699, 8, -1, 'Party foul against ELO, this is the 2012 re-recording which is worse.', '2026-04-14T16:35:49Z'),
  (4876, 701, 8, 1, NULL, '2026-04-14T16:35:49Z'),
  (4877, 703, 8, 1, NULL, '2026-04-14T16:35:49Z'),
  (4878, 693, 1, 0, 'Unspecial to me ', '2026-04-15T03:14:48Z'),
  (4879, 694, 1, 1, 'I liked the vibe and it was new for me. The oldies here remind me of the guardians of the galaxy mixtapes.', '2026-04-15T03:14:48Z'),
  (4880, 695, 1, 0, 'I wasn’t feeling this for this round ', '2026-04-15T03:14:48Z'),
  (4881, 696, 1, 0, 'Basic but a banger; you know it is ', '2026-04-15T03:14:48Z'),
  (4882, 697, 1, 0, 'It sounded like he was saying sacred heart haha if only ', '2026-04-15T03:14:48Z'),
  (4883, 698, 1, 1, 'I liked this too ', '2026-04-15T03:14:48Z'),
  (4884, 699, 1, -1, 'Sorry I just dont like it enough for it to cancel out the more obvious pick it is ', '2026-04-15T03:14:48Z'),
  (4885, 700, 1, 0, 'I’m ngl I dont understand this theme besides the space theme and moon theme but sure this is a nice piece ', '2026-04-15T03:14:48Z'),
  (4886, 701, 1, 1, 'Cute
I like the idea of a sweet song like this as you drift through the stars', '2026-04-15T03:14:48Z'),
  (4887, 702, 1, 1, 'I tried to submit this one and maybe it’s “obvious” but it’s one of the obvious ones that is also super good imo so it’ll get a vote from me ', '2026-04-15T03:14:48Z'),
  (4888, 703, 1, 0, 'I like this too and I think it being last is a disadvantage but I ultimately liked a couple of other similar genre ones better. Not enough notes etc ', '2026-04-15T03:14:48Z'),
  (4889, 693, 3, 1, 'This is a great “welcome back to Music League” song and I can picture it playing in space. ', '2026-04-16T13:05:15Z'),
  (4890, 694, 3, 1, 'A great example of why Queen is the greatest rock n roll band of all time. Beautiful, poignant, musically excellent. Best song about relativity', '2026-04-16T13:05:15Z'),
  (4891, 695, 3, 0, 'Not a space vibe to me', '2026-04-16T13:05:15Z'),
  (4892, 696, 3, 1, 'This would have tears floating around in the microgravity environment ', '2026-04-16T13:05:15Z'),
  (4893, 697, 3, 0, 'I love this song (possibly my favorite ELO), but I think there are better ELO choices for this round here. Not hype enough', '2026-04-16T13:05:15Z'),
  (4894, 698, 3, 0, 'I enjoyed this more than other Grateful Dead I’d heard', '2026-04-16T13:05:15Z'),
  (4895, 699, 3, 1, 'Senior launch engineer Sammy, lighting up an early morning cigarette in the Houston haze, turns the ignition on his 1969 Corvette droptop. As the small block roars to life and settles into a contented gurgle, he gazes up through his thick-rimmed glasses to the moon on the horizon, almost invisible as the sun begins its climb into the soft blue sky. It’s going to be quite a day. ', '2026-04-16T13:05:15Z'),
  (4896, 702, 3, -1, 'This is way too obvious, and today I feel like punishing that. If this is Shea I’m sorry', '2026-04-16T13:05:15Z'),
  (4897, 703, 3, 0, 'Nice enough, I just can’t picture this playing in the capsule ', '2026-04-16T13:05:15Z'),
  (4898, 694, 15, 1, 'Enjoyable ', '2026-04-16T14:35:09Z'),
  (4899, 695, 15, 2, 'The trumpets and drums are great', '2026-04-16T14:35:09Z'),
  (4900, 700, 15, 1, 'Outside the box.', '2026-04-16T14:35:09Z');
INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (4901, 701, 15, -1, NULL, '2026-04-16T14:35:09Z'),
  (4902, 702, 15, 0, 'Fun song, but probably NOT what an astronaut wants to hear while going up into space', '2026-04-16T14:35:09Z'),
  (4903, 693, 11, 1, 'Of the three ELO submissions this one struck me the most—it has this futuristic, frenetic energy without necessarily being explicitly about space travel, and I feel like if I were an astronaut this would be a great hype song ', '2026-04-17T05:32:12Z'),
  (4904, 694, 11, 1, 'Incredible pull for this category ', '2026-04-17T05:32:12Z'),
  (4905, 695, 11, 0, 'Real ones know that this song is sampled in Touch the Sky by Kanye West, which would also be a great pull for this category ', '2026-04-17T05:32:12Z'),
  (4906, 697, 11, 0, 'Thought about submitting this one. The most obviously space-y lyrically, but musically it also has a space vibe. Then again I guess this round has shown that ELO’s musical style just is the quintessential space vibe. Narrowly beat out ', '2026-04-17T05:32:12Z'),
  (4907, 698, 11, 1, 'I see the vision. 70s music just feels right for space. And the motif of still water/no wind blowing fits nicely too', '2026-04-17T05:32:12Z'),
  (4908, 699, 11, -1, 'Great song but it’s the most predictable of the ELO songs in this round (in part bc of the guardians of the galaxy association)', '2026-04-17T05:32:12Z'),
  (4909, 700, 11, 1, 'I LOVE JOSHUA BELL', '2026-04-17T05:32:12Z'),
  (4910, 702, 11, 0, 'It’s so good. I feel like it’s a bit too obvious a pick tho', '2026-04-17T05:32:12Z'),
  (4911, 703, 11, 0, 'This is for sure topical but musically it was just okay', '2026-04-17T05:32:12Z'),
  (4912, 693, 5, 1, NULL, '2026-04-17T20:59:21Z'),
  (4913, 697, 5, 1, NULL, '2026-04-17T20:59:21Z'),
  (4914, 698, 5, 1, NULL, '2026-04-17T20:59:21Z'),
  (4915, 699, 5, 1, NULL, '2026-04-17T20:59:21Z'),
  (4916, 702, 5, -1, NULL, '2026-04-17T20:59:21Z'),
  (4917, 693, 13, 1, 'Excellent, enjoyable, and cosmic pick.', '2026-04-17T21:10:23Z'),
  (4918, 697, 13, 1, 'I feel like ih ave to upvote every ELO song I hear in this one.', '2026-04-17T21:10:23Z'),
  (4919, 698, 13, -1, 'Don''t really get what you were going for with this one.', '2026-04-17T21:10:23Z'),
  (4920, 699, 13, 0, 'Sorry, this ELO song doesn''t quite work as a song to play ', '2026-04-17T21:10:23Z'),
  (4921, 700, 13, 1, 'Beautiful.  This would also be a great submission for "great songs to die in space to"', '2026-04-17T21:10:23Z'),
  (4922, 702, 13, 0, 'I feel like this was the most obvious pick for this category.  I hope I''m not punished for being basic.', '2026-04-17T21:10:23Z'),
  (4923, 703, 13, 1, 'i dug this one.  This is the sort of storytelling that should make it to space.

Musically, this was by far my favorite one on the list.', '2026-04-17T21:10:23Z'),
  (4924, 693, 9, 1, NULL, '2026-04-18T01:27:54Z'),
  (4925, 696, 9, 1, NULL, '2026-04-18T01:27:54Z'),
  (4926, 697, 9, 1, NULL, '2026-04-18T01:27:54Z'),
  (4927, 702, 9, 1, NULL, '2026-04-18T01:27:54Z'),
  (4928, 703, 9, -1, NULL, '2026-04-18T01:27:54Z'),
  (4929, 693, 16, 1, 'I’m ', '2026-04-18T01:50:39Z'),
  (4930, 697, 16, 1, NULL, '2026-04-18T01:50:39Z'),
  (4931, 698, 16, -1, NULL, '2026-04-18T01:50:39Z'),
  (4932, 702, 16, 1, NULL, '2026-04-18T01:50:39Z'),
  (4933, 703, 16, 1, NULL, '2026-04-18T01:50:39Z'),
  (4934, 694, 2, 0, 'I really enjoyed this. Really like the Brian May vocals. Just not quite as resonant to me as some other submissions. ', '2026-04-18T01:51:27Z'),
  (4935, 695, 2, 1, 'This was awesome and clever.', '2026-04-18T01:51:27Z'),
  (4936, 696, 2, 1, 'This is a fun read of the category ', '2026-04-18T01:51:27Z'),
  (4937, 699, 2, 0, 'I can get the idea (literally saying hello again to the blue sky after returning to Earth) but this seems like simultaneously the least imaginative ELO submission and also the least lyrically fitting. ', '2026-04-18T01:51:27Z'),
  (4938, 700, 2, 1, 'I can in fact literally imagine this being played as Artemis II careens past the far side of the moon. ', '2026-04-18T01:51:27Z'),
  (4939, 701, 2, -1, 'I want to think The Oh Hellos are a more inventive take on stomp clap slop, but every song I’ve heard other than Rio Grande and Soldier Poet King leaves me underwhelmed. This song is also not really at all the vibe I was picking up for this category. ', '2026-04-18T01:51:27Z'),
  (4940, 702, 2, 0, 'I cannot reward this as I think it is the most obvious possible pull for the category, and yet I am forbidden from downvoting, because this song is spectacular. Played it twice just out of reverence. Crazy he did this on only his second album. David Bowie one of the greatest to ever do it. ', '2026-04-18T01:51:27Z'),
  (4941, 703, 2, 1, 'Consummate Juddbait. I loved every part of this. Lyrically perfect, sort of mystical fit to the category as well. Perfect score, Dr. Roberts (I assume). ', '2026-04-18T01:51:27Z'),
