  (5192, 729, 9, 1, NULL, '2026-05-06T03:09:02Z'),
  (5193, 731, 2, 1, 'This is a good fusion of the two senses of bindlecore. ', '2026-05-06T03:10:58Z'),
  (5194, 730, 2, 1, 'Clever', '2026-05-06T03:10:58Z'),
  (5195, 740, 2, 0, 'I feel there are bindlier songs on this album ', '2026-05-06T03:10:58Z'),
  (5196, 738, 2, 0, 'Loser and bindle have overlap, but I don’t think they are interchangeable ', '2026-05-06T03:10:58Z'),
  (5197, 737, 2, -1, 'Not getting the vision here at all.', '2026-05-06T03:10:58Z'),
