INSERT INTO votes (id, submission_id, voter_id, points, comment, created_at) VALUES
  (5201, 732, 2, 0, 'This song rocks and I love hearing some Janis Joplin— but this is an obscure category and I’m voting based on my narrow interpretation of it. There’s clearly two schools of thought in interpreting what “bindle” means, and I like the songs that lean into the metaphorical sense more than the literal. This song is pretty upbeat and fun, which the essence of bindle is not. ', '2026-05-06T03:10:58Z'),
  (5202, 741, 8, 0, 'Gods-Not-Dead-Core. Doesn''t one of the Newsboys baptize the atheist professor at the end?', '2026-05-09T04:36:23Z'),
  (5203, 742, 8, 0, 'Hipster reject slop pile', '2026-05-09T04:36:23Z'),
  (5204, 743, 8, 0, 'Your fixation is strange, Eddie, and this was lazy. Now I play the schoolmarm and say, “do better.”', '2026-05-09T04:36:23Z'),
  (5205, 744, 8, 0, 'Great song but pathetically lazy, Alex', '2026-05-09T04:36:23Z'),
  (5206, 745, 8, 0, 'Liked it until I didn’t ', '2026-05-09T04:36:23Z'),
  (5207, 746, 8, 1, 'Finally a song actually about whales, the ostensible theme of the round. Misadventures of Flapjack-esque 1870s nautical scurvy-ridden diseased sailor energy. Masterpiece of a story.', '2026-05-09T04:36:23Z'),
  (5208, 748, 8, 0, 'This is a big poop platter with a glass of pee', '2026-05-09T04:36:23Z'),
  (5209, 749, 8, 0, 'Almost as bad as Gojira and twice as annoying', '2026-05-09T04:36:23Z'),
  (5210, 750, 8, -1, 'Joining the dogpile for what I presume to be the Joseph downvote. ', '2026-05-09T04:36:23Z'),
  (5211, 751, 8, 1, 'A whale with a crying Judd face for a face, being stripped of blubber by a team of Joseph and Peter clone fishermen ', '2026-05-09T04:36:23Z'),
  (5212, 752, 8, 1, 'Good', '2026-05-09T04:36:23Z'),
  (5213, 753, 8, 1, 'My favorite ', '2026-05-09T04:36:23Z'),
  (5214, 741, 6, 1, NULL, '2026-05-09T20:56:11Z'),
  (5215, 742, 6, -1, NULL, '2026-05-09T20:56:11Z'),
  (5216, 746, 6, 1, NULL, '2026-05-09T20:56:11Z'),
  (5217, 747, 6, 1, NULL, '2026-05-09T20:56:11Z'),
  (5218, 752, 6, 1, NULL, '2026-05-09T20:56:11Z'),
  (5219, 741, 2, 1, 'Listening to this song made me instantly think, oh shoot someone should have submitted a Veggietales song for this round. I had not yet seen the album cover ', '2026-05-10T23:24:45Z'),
  (5220, 742, 2, -1, 'Awesome song. Perhaps the most inexplicable ML submission of all time. Whatever OP was going for has filtered me completely ', '2026-05-10T23:24:45Z'),
  (5221, 743, 2, 0, 'Really liked this, wanted to upvote, but my research tells me there is actually no whale in Dire, Dire Docks', '2026-05-10T23:24:45Z'),
  (5222, 744, 2, 0, 'Cute. I really did almost give it to you on this one, but this was a surprisingly stacked round and there were too many pitch-perfect submissions', '2026-05-10T23:24:45Z'),
  (5223, 745, 2, 0, 'Impressive dredging this out of the <50 monthly listener Spotify mines, but it is nigh unlistenable and should probably remain there ', '2026-05-10T23:24:45Z'),
  (5224, 747, 2, 1, 'Beautiful. Tremendous pull', '2026-05-10T23:24:45Z'),
  (5225, 748, 2, 0, 'No, Joseph, no I will not read the lyrics — this is music league and I have to actually listen to the music, and should feel at least slightly rewarded by the experience. This isn’t clever lyrical concept league ', '2026-05-10T23:24:45Z'),
  (5226, 749, 2, 1, 'I actually really dig this and I am sort of shocked it exists, it’s perfect ', '2026-05-10T23:24:45Z'),
  (5227, 750, 2, 0, 'Clever but also boo', '2026-05-10T23:24:45Z'),
  (5228, 751, 2, 0, 'Pretty apt but this was my least favorite of the whaling folk song submissions ', '2026-05-10T23:24:45Z'),
  (5229, 752, 2, 1, 'Also excellent. I am really impressed with the extremely apt submissions this round, I thought it would be harder than this but apparently songs about whaling is a plentiful genre ', '2026-05-10T23:24:45Z'),
  (5230, 741, 1, 0, 'Yep this is about a whale ', '2026-05-11T17:44:07Z'),
  (5231, 742, 1, 0, 'Are the whales in the room with us?', '2026-05-11T17:44:07Z'),
  (5232, 743, 1, 0, 'Sorry, not holding its own with the other competitors', '2026-05-11T17:44:07Z'),
  (5233, 744, 1, -1, 'What upsets me most is that you wasted such an awesome song on a round that it doesn’t belong in', '2026-05-11T17:44:07Z'),
  (5234, 745, 1, 0, 'Ehhhhh', '2026-05-11T17:44:07Z'),
  (5235, 746, 1, 0, 'The voice sounded like a joke but there was potential here overall fs ', '2026-05-11T17:44:07Z'),
  (5236, 747, 1, 2, 'Stan is my one that got away 🫰
Flukes mentioned!!?', '2026-05-11T17:44:07Z'),
  (5237, 748, 1, 0, 'You knew what we would think but thanks for always being true to yourself ', '2026-05-11T17:44:07Z'),
  (5238, 749, 1, 0, 'Ehh ', '2026-05-11T17:44:07Z'),
  (5239, 750, 1, 0, 'I like this enough but the whale theme is lacking ', '2026-05-11T17:44:07Z'),
  (5240, 751, 1, 0, '🥀🪦🐋🥺', '2026-05-11T17:44:07Z'),
  (5241, 752, 1, 1, 'Love the Pogues ', '2026-05-11T17:44:07Z'),
  (5242, 753, 1, 1, 'This one is cute and my niece and nephew know it so positive connotations for me (it might get hate so I have to show it some love)', '2026-05-11T17:44:07Z'),
  (5243, 741, 4, 0, 'I know there''s context here, but without it this song is super annoying', '2026-05-11T19:17:14Z'),
  (5244, 742, 4, -1, 'No? 

This gets my downvote because I can’t even place the basic idea of why this was chosen. At least for the “Noah and the whale” song I can tell it’s because of the band name even though that the bad reason ', '2026-05-11T19:17:14Z'),
  (5245, 743, 4, 0, 'Spiritually this is what I imagine whales listen to', '2026-05-11T19:17:14Z'),
  (5246, 744, 4, 0, 'He''s talking about the Miami Dolphins y''all', '2026-05-11T19:17:14Z'),
  (5247, 745, 4, 1, 'I was hoping for one song that really captures the inexplicable hold the whale can have on the heart of man. There''s a reason so many songs and concepts revolve around this idea, and I love using weird music notation to explore it. ', '2026-05-11T19:17:14Z'),
  (5248, 746, 4, 0, 'This reminds me of No Country For Old Men. The whale representing chance - you can do everything you think you should and pursue it with singlemindedness, but chance might have other things in mind. And I don''t mean the coin flip thing Judd, I mean the car accident at the end.', '2026-05-11T19:17:14Z'),
  (5249, 747, 4, 1, 'No notes. It''s just too perfect. ', '2026-05-11T19:17:14Z'),
  (5250, 748, 4, 1, 'I thought about submitting this but I didn''t because you can''t understand it. Would love to hear this as a Rush song. I do like it a lot tho. I love that somehow this is a common theme. ', '2026-05-11T19:17:14Z'),
  (5251, 749, 4, 0, 'This is similar in theme to The Last Leviathan, but their Gen X smugness irks me ', '2026-05-11T19:17:14Z'),
